// === GUARDARRAÍL DE ENTRADA ===
// Bloquea: prompt injection, contenido prohibido y PII obvia.

const body = $input.first().json.body || $input.first().json;
const prompt = (body.prompt || '').toString();

if (!prompt.trim()) {
  return [{ json: { allowed: false, categoria: 'vacio', reason: 'prompt vacío', prompt: '' } }];
}
if (prompt.length > 4000) {
  return [{ json: { allowed: false, categoria: 'longitud', reason: 'prompt demasiado largo (>4000)', prompt } }];
}

const INJECTION = [
  /ignore (all|previous|prior) instructions/i,
  /disregard (all|previous|the) (system|earlier)/i,
  /act as (a |an )?(dan|jailbreak|admin)/i,
  /system prompt/i,
  /reveal (your|the) (system|hidden|secret) (prompt|instructions)/i,
  /\bjailbreak\b/i,
  /\bDAN\b/,
  /pretend (you are|to be)/i,
  /ignora (todas )?(las )?instrucciones (anteriores|previas)/i,
  /olvida (todas )?(las )?instrucciones/i
];

const PROHIBIDO = [
  /how (to|do i) (make|build|create|synthesize) (a |an )?(bomb|explosive|weapon)/i,
  /child (porn|abuse|sexual)/i,
  /\bcsam\b/i,
  /(buy|sell|acquire) (drugs|cocaine|heroin|meth)/i,
  /c[oó]mo (hacer|fabricar|construir) (una |un )?bomba/i
];

const PII = [
  /\b\d{16}\b/,
  /\b\d{8}[a-z]\b/i,
  /\bcvv\s*:?\s*\d{3,4}\b/i
];

for (const re of INJECTION) {
  if (re.test(prompt)) {
    return [{ json: { allowed: false, categoria: 'prompt_injection', reason: 'prompt injection detectado', prompt } }];
  }
}
for (const re of PROHIBIDO) {
  if (re.test(prompt)) {
    return [{ json: { allowed: false, categoria: 'contenido_prohibido', reason: 'tema prohibido', prompt } }];
  }
}
for (const re of PII) {
  if (re.test(prompt)) {
    return [{ json: { allowed: false, categoria: 'pii', reason: 'PII en el prompt', prompt } }];
  }
}

return [{ json: { allowed: true, prompt } }];

