// === GUARDARRAÍL DE SALIDA ===
// Lee la respuesta del LLM (Ollama / DeepSeek / OpenAI) y la bloquea o
// sanitiza si contiene contenido inapropiado.

const data = $input.first().json;

// Soporta varias formas posibles de respuesta:
//   Ollama:    { message: { content: '...' } }
//   OpenAI:    { choices: [{ message: { content: '...' }}] }
//   Otros:     { response: '...' } o { text: '...' }
let texto = '';
if (data.message && data.message.content) {
  texto = data.message.content;
} else if (data.choices && data.choices[0] && data.choices[0].message) {
  texto = data.choices[0].message.content;
} else if (typeof data.response === 'string') {
  texto = data.response;
} else if (typeof data.text === 'string') {
  texto = data.text;
}

if (!texto) {
  return [{ json: { safe: false, categoria: 'sin_respuesta', reason: 'el LLM no devolvió texto', sanitized: 'No se pudo generar respuesta.' } }];
}

const BANEADO = [
  /\b(idiota|imbécil|imbecil|estúpido|estupido|gilipollas)\b/i,
  /\b(suicidarse|suicidio|matarse|autolesion)/i,
  /\bmatar\s+a\s+/i
];

for (const re of BANEADO) {
  if (re.test(texto)) {
    return [{ json: {
      safe: false,
      categoria: 'salida_inapropiada',
      reason: 'la respuesta del modelo contiene contenido bloqueado',
      sanitized: 'No puedo proporcionar esa respuesta.'
    }}];
  }
}

return [{ json: { safe: true, sanitized: texto } }];
